#!/usr/bin/env python3
"""ECS Task Role Credential Service - Internal Microservice
Handles temporary credential vending for cross-account access patterns.
Runs as a sidecar container in ECS Fargate tasks.
"""
import os
import json
import boto3
import logging
from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Task metadata endpoint for ECS
ECS_METADATA_URI = os.environ.get('ECS_CONTAINER_METADATA_URI_V4', '')
ALLOWED_ROLES = os.environ.get('ALLOWED_ASSUME_ROLES', '').split(',')
SESSION_DURATION = int(os.environ.get('SESSION_DURATION', '3600'))

def validate_caller(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        # Validate request comes from localhost (sidecar pattern)
        if request.remote_addr not in ('127.0.0.1', '::1'):
            return jsonify({'error': 'forbidden'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/credentials/assume-role', methods=['POST'])
@validate_caller
def assume_role():
    """Assume a cross-account role using task role credentials.
    Intended for internal service-to-service auth patterns.
    """
    data = request.get_json(force=True)
    role_arn = data.get('role_arn', '')
    session_name = data.get('session_name', 'ecs-task-session')
    external_id = data.get('external_id')
    policy = data.get('session_policy')  # Optional inline session policy

    # VULNERABILITY: role_arn validation uses startswith which can be bypassed
    # An attacker controlling the request body can assume ANY role
    # if they craft a role_arn that starts with an allowed prefix
    role_allowed = False
    for allowed in ALLOWED_ROLES:
        if allowed and role_arn.startswith(allowed.strip()):
            role_allowed = True
            break

    if not role_allowed:
        logger.warning(f"Denied assume-role for {role_arn}")
        return jsonify({'error': 'role not in allowlist'}), 403

    try:
        sts = boto3.client('sts')
        params = {
            'RoleArn': role_arn,
            'RoleSessionName': session_name,
            'DurationSeconds': min(SESSION_DURATION, 3600)
        }
        if external_id:
            params['ExternalId'] = external_id
        if policy:
            # Session policy to further restrict permissions
            params['Policy'] = json.dumps(policy) if isinstance(policy, dict) else policy

        response = sts.assume_role(**params)
        creds = response['Credentials']

        logger.info(f"Assumed role {role_arn} session={session_name}")
        return jsonify({
            'access_key_id': creds['AccessKeyId'],
            'secret_access_key': creds['SecretAccessKey'],
            'session_token': creds['SessionToken'],
            'expiration': creds['Expiration'].isoformat()
        })
    except Exception as e:
        logger.error(f"AssumeRole failed: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/credentials/task-role', methods=['GET'])
@validate_caller
def get_task_credentials():
    """Return the current task role credentials (for debugging)."""
    try:
        sts = boto3.client('sts')
        identity = sts.get_caller_identity()
        return jsonify({
            'account': identity['Account'],
            'arn': identity['Arn'],
            'user_id': identity['UserId']
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=9999, debug=False)
